   215→    const label = document.getElementById('strengthLabel');
   216→    if (!val) { bar.style.display='none'; label.textContent=''; return; }
   217→    bar.style.display='block';
   218→    let s = 0;
   219→    if (val.length >= 8) s++;
   220→    if (/[A-Z]/.test(val)) s++;
   221→    if (/[0-9]/.test(val)) s++;
   222→    if (/[^A-Za-z0-9]/.test(val)) s++;
   223→    const cfgs = [
   224→        {p:'25%',c:'#ef4444',t:'Lemah'},
   225→        {p:'50%',c:'#f6af23',t:'Cukup'},
   226→        {p:'75%',c:'#c84ddf',t:'Kuat'},
   227→        {p:'100%',c:'#10b981',t:'Sangat Kuat'},
   228→    ];
   229→    const cfg = cfgs[s-1] || cfgs[0];
   230→    fill.style.width=cfg.p; fill.style.background=cfg.c;
   231→    label.textContent=cfg.t; label.style.color=cfg.c;
   232→});
